import os
import tempfile
import pytest
from envcfg import load, EnvCfgError


def test_defaults_only():
    """Defaults alone are returned unchanged."""
    cfg = load({"a": 1, "b": "hello"})
    assert cfg == {"a": 1, "b": "hello"}


def test_defaults_override_by_toml():
    """TOML values override defaults."""
    defaults = {"port": 8000, "host": "localhost"}
    toml_path = tempfile.mktemp(suffix=".toml")
    with open(toml_path, "w") as f:
        f.write("port = 9000\nhost = \"0.0.0.0\"\n")
    cfg = load(defaults, toml_path)
    assert cfg == {"port": 9000, "host": "0.0.0.0"}
    os.remove(toml_path)


def test_defaults_override_by_env():
    """Env vars override defaults and TOML."""
    defaults = {"port": 8000, "host": "localhost"}
    toml_path = tempfile.mktemp(suffix=".toml")
    with open(toml_path, "w") as f:
        f.write("port = 9000\nhost = \"0.0.0.0\"\n")
    env = os.environ.copy()
    env["APP__PORT"] = "12345"
    env["APP__HOST"] = "127.0.0.1"
    cfg = load(defaults, toml_path, env=env)
    assert cfg == {"port": 12345, "host": "127.0.0.1"}
    os.remove(toml_path)


def test_missing_toml_file_is_skipped():
    """Missing TOML file is silently skipped."""
    cfg = load({"a": 1}, toml_path="/nonexistent.toml")
    assert cfg == {"a": 1}


def test_nested_keys_from_env():
    """Nested keys are assembled correctly from env vars."""
    defaults = {"server": {"port": 8000, "host": "localhost"}}
    env = os.environ.copy()
    env["APP__SERVER__PORT"] = "9000"
    env["APP__SERVER__HOST"] = "0.0.0.0"
    cfg = load(defaults, env=env)
    assert cfg == {"server": {"port": 9000, "host": "0.0.0.0"}}


def test_bool_coercion():
    """Bool coercion accepts true/false/1/0/yes/no."""
    defaults = {"debug": False}
    env = os.environ.copy()
    env["APP__DEBUG"] = "true"
    cfg = load(defaults, env=env)
    assert cfg == {"debug": True}


